begin;
create function pg_temp.check_approve(ok boolean,msg text) returns void language plpgsql as $$begin if not coalesce(ok,false) then raise exception '%',msg;end if;raise notice 'PASS: %',msg;end$$;
create function pg_temp.expect_approve(stmt text,code text,msg text) returns void language plpgsql as $$begin begin execute stmt;exception when others then if sqlstate=code then raise notice 'PASS: %',msg;return;else raise;end if;end;raise exception 'Expected failure: %',msg;end$$;
insert into auth.users(id,email_confirmed_at) values('60040000-0000-4000-8000-000000000001',now());
insert into public.properties values('hu60-approve-p','60040000-0000-4000-8000-000000000001','{}','2026-10-11T00:00:00Z');
select pg_temp.check_approve(not has_function_privilege('authenticated','public.approve_computed_scenario(uuid,text,timestamptz,timestamptz,text,uuid,jsonb)','execute') and not has_function_privilege('anon','public.approve_computed_scenario(uuid,text,timestamptz,timestamptz,text,uuid,jsonb)','execute'),'approval server only');
set local role service_role;
select pg_temp.expect_approve($q$select public.approve_computed_scenario('60040000-0000-4000-8000-000000000001','hu60-approve-p','2026-10-11T00:00:00Z',null,'Incomplete','60040000-0000-4000-8000-000000000010','{"property":{"id":"hu60-approve-p"},"engine":"test","result":{"missing":["ARV"]}}')$q$,'22023','missing fields denied');
select pg_temp.expect_approve($q$select public.approve_computed_scenario('60040000-0000-4000-8000-000000000001','hu60-approve-p','2026-10-11T00:00:00Z',null,'Incomplete','60040000-0000-4000-8000-000000000010','{"property":{"id":"hu60-approve-p"},"engine":"test","result":{"missing":[]},"comparison":{"errors":["missing"]}}')$q$,'22023','comparison errors denied');
reset role;
create function pg_temp.fail_approve_audit() returns trigger language plpgsql as $$begin if new.property_id='hu60-approve-p' then raise exception using errcode='P0001',message='Synthetic failure';end if;return new;end$$;
create trigger hu60_test_approve_failure before insert on public.audit_events for each row execute function pg_temp.fail_approve_audit();
set local role service_role;
select pg_temp.expect_approve($q$select public.approve_computed_scenario('60040000-0000-4000-8000-000000000001','hu60-approve-p','2026-10-11T00:00:00Z',null,'Rollback','60040000-0000-4000-8000-000000000011','{"property":{"id":"hu60-approve-p"},"engine":"test","result":{"missing":[]}}')$q$,'P0001','approval audit failure propagates');
reset role;
select pg_temp.check_approve(not exists(select 1 from public.analysis_baselines where property_id='hu60-approve-p') and not exists(select 1 from public.analysis_scenarios where property_id='hu60-approve-p'),'both baseline and snapshot rolled back');
drop trigger hu60_test_approve_failure on public.audit_events;
set local role service_role;
select public.approve_computed_scenario('60040000-0000-4000-8000-000000000001','hu60-approve-p','2026-10-11T00:00:00Z',null,'Approved','60040000-0000-4000-8000-000000000012','{"property":{"id":"hu60-approve-p"},"engine":"test","result":{"missing":[]}}');
select pg_temp.check_approve((public.approve_computed_scenario('60040000-0000-4000-8000-000000000001','hu60-approve-p','2026-10-11T00:00:00Z',null,'Approved','60040000-0000-4000-8000-000000000012')->>'replayed')::boolean,'approval receipt replay');
select pg_temp.expect_approve($q$select public.approve_computed_scenario('60040000-0000-4000-8000-000000000001','hu60-approve-p','2026-10-11T00:00:00Z',null,'Second','60040000-0000-4000-8000-000000000013','{"property":{"id":"hu60-approve-p"},"engine":"test","result":{"missing":[]}}')$q$,'40001','existing baseline cannot be replaced');
reset role;
select pg_temp.check_approve((select count(*)=1 from public.analysis_baselines where property_id='hu60-approve-p') and (select count(*)=1 from public.analysis_scenarios where property_id='hu60-approve-p') and (select count(*)=1 from public.audit_events where property_id='hu60-approve-p'),'one baseline snapshot and audit');
select pg_temp.check_approve(not has_table_privilege('service_role','public.analysis_baselines','insert'),'no direct baseline insert');
rollback;
